import * as React from "react"
import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * Where a person asks the AI about the object on screen.
 * The placeholder names that object, so the question has a context.
 * States: empty · hover · focus · filled (send on) · sending · error (keeps the text).
 */
export interface AskInputProps {
  object: string
  sending?: boolean
  error?: string
  defaultValue?: string
  onSend?: (text: string) => void
  className?: string
}

export function AskInput({ object, sending = false, error, defaultValue = "", onSend, className }: AskInputProps) {
  const [value, setValue] = React.useState(defaultValue)
  const canSend = value.trim().length > 0 && !sending
  return (
    <div className={cn("grid w-full max-w-[340px] gap-1.5", className)}>
      <form
        data-slot="ask-input"
        onSubmit={(e) => { e.preventDefault(); if (canSend) onSend?.(value) }}
        className={cn(
          "flex h-11 items-center gap-2 bg-background pr-[5px] pl-3.5 shadow-[inset_0_0_0_1px_var(--border)] transition-shadow duration-200 hover:shadow-[inset_0_0_0_1px_var(--muted-foreground)] focus-within:shadow-[inset_0_0_0_1.5px_var(--foreground)]",
          error && "shadow-[inset_0_0_0_1.5px_var(--gc-accent)] hover:shadow-[inset_0_0_0_1.5px_var(--gc-accent)]",
          sending && "opacity-70"
        )}
      >
        <input
          value={value}
          onChange={(e) => setValue(e.target.value)}
          disabled={sending}
          placeholder={`Ask about ${object}…`}
          aria-label={`Ask Green Control about ${object}`}
          aria-invalid={!!error || undefined}
          className="h-full min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
        />
        <button
          type="submit"
          disabled={!canSend}
          aria-label="Send"
          className="grid size-[34px] cursor-pointer place-items-center bg-primary text-primary-foreground outline-none transition-colors focus-visible:outline-[1.5px] focus-visible:outline-offset-2 focus-visible:outline-foreground disabled:cursor-not-allowed disabled:bg-secondary disabled:text-muted-foreground"
        >
          {sending ? <Spinner /> : <svg viewBox="0 0 14 14" className="size-3.5 fill-none stroke-current stroke-[1.6]"><path d="M2.5 7h9M7.5 3l4 4-4 4" /></svg>}
        </button>
      </form>
      {error && <span role="alert" className="text-[13px] text-signal">{error}</span>}
    </div>
  )
}
